WITH scored AS (SELECT *, AVG(amount) OVER w_recent AS amount_avg_7d, NTILE(4) OVER (PARTITION BY method ORDER BY amount DESC, id) AS amount_bucket, LAST_VALUE(amount, TRUE) OVER (PARTITION BY method, status ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_amount FROM payments WINDOW w_recent AS (ORDER BY CAST(paid_at AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW)) SELECT id, order_id, method, amount, status, amount_avg_7d, amount_bucket FROM scored;
